import type { LegalPassage } from "../types";

type P = Partial<LegalPassage> & Pick<LegalPassage, "id" | "sourceId" | "ref" | "heading" | "text">;

/** OECD-layer passage: applies in every jurisdiction that has enacted the Rules unless the passage says otherwise. */
function p(x: P): LegalPassage {
  return {
    textKind: "paraphrase",
    effectiveFrom: "2024-01-01",
    effectiveTo: null,
    jurisdiction: "*",
    topics: [],
    ruleIds: [],
    electionIds: [],
    instrumentIds: [],
    gapIds: [],
    ...x,
  };
}

const MR = "OECD-MR-2021";

export const OECD_PASSAGES: LegalPassage[] = [
  /* ------------------------------------------------------------ Chapter 1 */
  p({ id: "LP-MR-1.1", sourceId: MR, ref: "Art. 1.1.1–1.1.2", heading: "Scope — consolidated revenue threshold", text: "The GloBE Rules apply to the Constituent Entities of an MNE Group whose consolidated revenue in the Ultimate Parent Entity's consolidated financial statements is EUR 750 million or more in at least two of the four Fiscal Years immediately preceding the tested Fiscal Year. Where one of those years is shorter or longer than twelve months the threshold is adjusted proportionally for that year.", topics: ["scope", "750m", "revenue threshold", "two of four", "short year"], ruleIds: ["OECD-SCOPE-750"], gapIds: ["G-SCOPE"], href: "/scope" }),
  p({ id: "LP-MR-1.2-1.3", sourceId: MR, ref: "Art. 1.2–1.3", heading: "Group, MNE Group and Constituent Entity", text: "A Group is a collection of Entities related through ownership or control such that their assets, liabilities, income, expenses and cash flows are consolidated line by line in the UPE's consolidated financial statements, or would be but for size, materiality or held-for-sale exclusions. An MNE Group has at least one Entity or Permanent Establishment outside the UPE's jurisdiction. A Constituent Entity is any Entity included in the Group, and any Permanent Establishment of a Main Entity that is itself a Constituent Entity; Excluded Entities are carved out.", topics: ["group", "constituent entity", "consolidation", "permanent establishment", "mne group"], gapIds: ["G-SITUS"], href: "/entities" }),
  p({ id: "LP-MR-1.4", sourceId: MR, ref: "Art. 1.4", heading: "Ultimate Parent Entity", text: "The Ultimate Parent Entity is the Entity that owns, directly or indirectly, a Controlling Interest in any other Entity and is not itself owned with a Controlling Interest by another Entity; or the Main Entity of a Group consisting of a single Entity and its Permanent Establishments.", topics: ["upe", "ultimate parent", "controlling interest"], href: "/group" }),
  p({ id: "LP-MR-1.5", sourceId: MR, ref: "Art. 1.5.1–1.5.3", heading: "Excluded Entities and the election to include them", text: "Governmental Entities, International Organisations, Non-profit Organisations, Pension Funds, and Investment Funds or Real Estate Investment Vehicles that are the UPE are Excluded Entities. So are Entities at least 95% owned by Excluded Entities that hold assets or invest funds for them or only carry on ancillary activities, and Entities at least 85% owned by Excluded Entities whose income is substantially all Excluded Dividends or Excluded Equity Gains. Under Art. 1.5.3 the Filing Constituent Entity may make a Five-Year Election not to treat an Art. 1.5.2 Entity as excluded.", topics: ["excluded entity", "pension fund", "investment fund", "governmental entity", "non-profit", "95%", "85%", "election"], electionIds: ["OECD_1.5.3"], instrumentIds: ["dgtopuptax7"], gapIds: ["G-SITUS"], href: "/entities" }),

  /* ------------------------------------------------------------ Chapter 2 */
  p({ id: "LP-MR-2.1.1", sourceId: MR, ref: "Art. 2.1.1–2.1.3", heading: "IIR — Ultimate Parent Entity and Intermediate Parent Entities", text: "A UPE located in a jurisdiction with a Qualified IIR pays Top-up Tax equal to its Allocable Share of the Top-up Tax of each Low-Taxed Constituent Entity in which it holds an Ownership Interest. An Intermediate Parent Entity applies the IIR to its Allocable Share only where the UPE is not required to apply a Qualified IIR and it is not itself owned with a Controlling Interest by another Intermediate Parent Entity that applies one.", topics: ["iir", "income inclusion rule", "upe", "intermediate parent", "top-down"], gapIds: ["G-ORDER"], href: "/allocation" }),
  p({ id: "LP-MR-2.1.4", sourceId: MR, ref: "Art. 2.1.4–2.1.5", heading: "IIR — Partially-Owned Parent Entity", text: "A Partially-Owned Parent Entity — a Constituent Entity, other than the UPE, more than 20% of whose Ownership Interests in profits are held directly or indirectly by persons that are not Constituent Entities — located in a jurisdiction with a Qualified IIR applies the IIR to its Allocable Share of the Top-up Tax of its Low-Taxed Constituent Entities regardless of whether the UPE also applies an IIR, unless all of its Ownership Interests are held by another POPE that is subject to a Qualified IIR. The UPE then takes only the residual under the Art. 2.3 offset.", topics: ["pope", "partially-owned parent", "20%", "iir", "entity test", "split ownership"], ruleIds: ["OECD-POPE-214"], href: "/entities" }),
  p({ id: "LP-MR-2.2", sourceId: MR, ref: "Art. 2.2.1–2.2.4", heading: "Allocable Share and Inclusion Ratio", text: "A Parent Entity's Allocable Share of a Low-Taxed Constituent Entity's Top-up Tax is that Top-up Tax multiplied by the Parent's Inclusion Ratio. The Inclusion Ratio is the LTCE's GloBE Income for the year less the GloBE Income attributable to Ownership Interests held by other owners, divided by the LTCE's GloBE Income. The amount attributable to other owners is measured as if the LTCE's income were distributed through the ownership chain under the UPE's accounting standard.", topics: ["inclusion ratio", "allocable share", "ownership interest", "2.2.2"], ruleIds: ["OECD-IR-222", "OECD-POPE-214"], href: "/allocation" }),
  p({ id: "LP-MR-2.3", sourceId: MR, ref: "Art. 2.3", heading: "IIR offset mechanism", text: "Where a Parent Entity holds an Ownership Interest in a Low-Taxed Constituent Entity indirectly through an Intermediate Parent Entity or Partially-Owned Parent Entity that is itself subject to a Qualified IIR for the year, the higher Parent's Top-up Tax under the IIR is reduced by the portion of its Allocable Share that is brought into charge by the lower Parent. No amount of Top-up Tax is charged twice.", topics: ["offset", "double counting", "iir", "pope", "intermediate parent"], ruleIds: ["OECD-POPE-214"], href: "/allocation" }),
  p({ id: "LP-MR-2.4-2.5", sourceId: MR, ref: "Art. 2.4–2.5", heading: "UTPR — charge and Total UTPR Top-up Tax Amount", text: "Constituent Entities located in a jurisdiction with a Qualified UTPR are denied a deduction, or bear an equivalent adjustment, producing additional cash tax expense equal to the UTPR Top-up Tax Amount allocated to that jurisdiction. The Total UTPR Top-up Tax Amount is the sum of the Top-up Tax of every Low-Taxed Constituent Entity of the group, reduced to zero for an LTCE whose Ownership Interests are all held by Parent Entities applying a Qualified IIR, and otherwise reduced by the Allocable Share already brought into charge under a Qualified IIR.", topics: ["utpr", "undertaxed profits rule", "backstop", "denial of deduction"], ruleIds: ["OECD-UTPR-26"], gapIds: ["G-ORDER", "G-UTPR"], href: "/allocation" }),
  p({ id: "LP-MR-2.6", sourceId: MR, ref: "Art. 2.6", heading: "UTPR — allocation key", text: "The Total UTPR Top-up Tax Amount is allocated to each UTPR jurisdiction by a percentage equal to 50% of the jurisdiction's share of the group's employees plus 50% of its share of the group's Net Book Value of Tangible Assets, counting only Constituent Entities located in UTPR jurisdictions and excluding Investment Entities. A jurisdiction whose allocation in a prior year did not result in additional cash tax expense is given a zero percentage until it does.", topics: ["utpr", "allocation", "employees", "tangible assets", "50%", "2.6"], ruleIds: ["OECD-UTPR-26"], instrumentIds: ["dgtopuptax5"], gapIds: ["G-UTPR"], href: "/allocation" }),

  /* ------------------------------------------------------------ Chapter 3 */
  p({ id: "LP-MR-3.1", sourceId: MR, ref: "Art. 3.1.2–3.1.3", heading: "Financial Accounting Net Income or Loss and the accounting standard", text: "A Constituent Entity's Financial Accounting Net Income or Loss is the net income or loss determined for it in preparing the UPE's consolidated financial statements, before consolidation adjustments eliminating intra-group transactions. Where it is not reasonably practicable to determine that amount on the UPE's standard, another Acceptable or Authorised Financial Accounting Standard may be used if the information is reliable and Permanent Differences above EUR 1 million are conformed to the UPE's standard.", topics: ["fanil", "accounting standard", "acceptable financial accounting standard", "authorised", "eur 1 million", "permanent difference"], electionIds: ["OECD_3.1.3"], instrumentIds: ["dgtopuptax1"], gapIds: ["G-GAAP", "G-FANIL"], href: "/globe-income" }),
  p({ id: "LP-MR-3.2.1", sourceId: MR, ref: "Art. 3.2.1", heading: "Adjustments to arrive at GloBE Income or Loss", text: "Financial Accounting Net Income or Loss is adjusted for: (a) Net Taxes Expense; (b) Excluded Dividends; (c) Excluded Equity Gain or Loss; (d) Included Revaluation Method Gain or Loss; (e) gains or losses on assets and liabilities excluded under Art. 6.3; (f) Asymmetric Foreign Currency Gains or Losses; (g) Policy Disallowed Expenses — illegal payments and fines or penalties of EUR 50,000 or more; (h) Prior Period Errors and Changes in Accounting Principles; and (i) Accrued Pension Expense.", topics: ["globe income", "adjustments", "3.2.1", "net taxes expense", "policy disallowed", "pension", "asymmetric fx"], electionIds: ["SETR_FX", "SETR_PEN"], gapIds: ["G-FANIL"], href: "/globe-income" }),
  p({ id: "LP-MR-3.2.1b", sourceId: MR, ref: "Art. 3.2.1(b) · Art. 10.1 'Excluded Dividends', 'Portfolio Shareholding'", heading: "Excluded Dividends", text: "Dividends and other distributions received in respect of an Ownership Interest are excluded from GloBE Income, except those on a Short-term Portfolio Shareholding — an Ownership Interest carrying rights to less than 10% of the profits, capital, reserves or votes of the issuer, economically held for less than one year at the date of distribution. An Ownership Interest means any equity interest that carries rights to profits, capital or reserves.", topics: ["dividend", "excluded dividend", "portfolio shareholding", "10%", "one year", "ownership interest"], ruleIds: ["OECD-DIV-EXCL"], electionIds: ["OECD_3.2.1b"], href: "/globe-income" }),
  p({ id: "LP-MR-3.2.1c", sourceId: MR, ref: "Art. 3.2.1(c) · Art. 10.1 'Excluded Equity Gain or Loss'", heading: "Excluded Equity Gain or Loss", text: "Gains and losses on Ownership Interests are excluded from GloBE Income where they arise from changes in fair value of an Ownership Interest other than a Portfolio Shareholding, from equity-method accounting for an Ownership Interest, or from the disposition of an Ownership Interest other than a Portfolio Shareholding. Related Covered Taxes are removed under Art. 4.1.3(a).", topics: ["equity gain", "excluded equity", "fair value", "equity method", "disposition"], electionIds: ["OECD_3.2.1c_eq", "OECD_3.2.1c_fx"], href: "/globe-income" }),
  p({ id: "LP-MR-3.2.2", sourceId: MR, ref: "Art. 3.2.2", heading: "Stock-based compensation election", text: "At the election of the Filing Constituent Entity, the amount allowed as a deduction for stock-based compensation in computing a Constituent Entity's local taxable income is substituted for the expense recognised in its financial accounts. Where an option expires unexercised, previously deducted expense is added back in that year. The election is a Five-Year Election applied consistently to all Constituent Entities located in the jurisdiction; where it is made after some expense has already been recognised, the cumulative difference is included in the year of election.", topics: ["stock compensation", "share-based payment", "3.2.2", "election", "five-year", "local deduction"], ruleIds: ["OECD-ELEC-2026"], electionIds: ["OECD_3.2.2"], href: "/elections" }),
  p({ id: "LP-MR-3.2.3", sourceId: MR, ref: "Art. 3.2.3", heading: "Arm's length principle between Constituent Entities", text: "A transaction between Constituent Entities located in different jurisdictions that is not recorded at the same amount in both entities' accounts, or is not consistent with the Arm's Length Principle, is adjusted so that it is. A loss from a sale or transfer of an asset between Constituent Entities in the same jurisdiction that is not recorded consistently with the Arm's Length Principle is recomputed on that basis.", topics: ["arm's length", "transfer pricing", "intra-group", "3.2.3"], electionIds: ["SETR_TP"], href: "/globe-income" }),
  p({ id: "LP-MR-3.2.4", sourceId: MR, ref: "Art. 3.2.4 · Art. 10.1 'Qualified Refundable Tax Credit'", heading: "Refundable tax credits", text: "A Qualified Refundable Tax Credit — one payable in cash or cash equivalents within four years of the Constituent Entity satisfying its conditions — is treated as income in computing GloBE Income, not as a reduction of Covered Taxes. A Non-Qualified Refundable Tax Credit is treated as a reduction of Covered Taxes. This determines whether an incentive lowers the ETR through the numerator or dilutes it through the denominator.", topics: ["qrtc", "refundable tax credit", "incentive", "four years", "non-qualified"], electionIds: ["SETR_QRTC"], gapIds: ["G-BOI"], href: "/incentives" }),
  p({ id: "LP-MR-3.2.5", sourceId: MR, ref: "Art. 3.2.5", heading: "Realisation principle election", text: "The Filing Constituent Entity may make a Five-Year Election to determine gains and losses on assets and liabilities that are subject to fair value or impairment accounting on the realisation principle instead. The election applies to all Constituent Entities in the jurisdiction, and may be limited to tangible assets or to Investment Entities. On revocation, the difference between fair value and carrying value at the start of the revocation year is brought into GloBE Income.", topics: ["realisation", "fair value", "impairment", "3.2.5", "election"], electionIds: ["OECD_3.2.5"], href: "/globe-income" }),
  p({ id: "LP-MR-3.2.6", sourceId: MR, ref: "Art. 3.2.6", heading: "Aggregate asset gain election", text: "The Filing Constituent Entity may make an Annual Election to spread a Net Asset Gain on Local Tangible Assets: the gain is first offset against Net Asset Losses of Constituent Entities in the jurisdiction in the four preceding Fiscal Years, and any remainder is spread evenly over the five-year Look-back Period. Covered Taxes on the gain are excluded from Adjusted Covered Taxes for the election year.", topics: ["aggregate asset gain", "tangible assets", "look-back", "3.2.6", "annual election"], electionIds: ["OECD_3.2.6"], href: "/globe-income" }),
  p({ id: "LP-MR-3.2.7", sourceId: MR, ref: "Art. 3.2.7", heading: "Intragroup Financing Arrangements", text: "Expense attributable to an Intragroup Financing Arrangement is excluded from the GloBE Income of a Low-Tax Entity where it can reasonably be anticipated, over the expected duration of the arrangement, to increase that entity's expenses without a commensurate increase in the taxable income of the High-Tax Counterparty.", topics: ["intragroup financing", "low-tax entity", "high-tax counterparty", "3.2.7"], href: "/globe-income" }),
  p({ id: "LP-MR-3.2.8", sourceId: MR, ref: "Art. 3.2.8", heading: "Consolidated accounting treatment election for same-jurisdiction entities", text: "The Filing Constituent Entity may make a Five-Year Election to apply the UPE's consolidated accounting treatment to eliminate income, expense, gains and losses from transactions between Constituent Entities located in the same jurisdiction that are included in a tax consolidation group. On revocation, the previously eliminated items are appropriately brought back into account.", topics: ["intra-group", "consolidation", "tax group", "3.2.8", "election"], electionIds: ["OECD_3.2.8"], href: "/globe-income" }),
  p({ id: "LP-MR-3.2.9-10", sourceId: MR, ref: "Art. 3.2.9–3.2.10", heading: "Insurance policyholder taxes and Additional Tier One Capital", text: "An insurance company excludes from GloBE Income amounts charged to policyholders for taxes it paid on returns to them, and includes returns to policyholders not reflected in its net income to the extent the corresponding movement in policyholder liabilities is reflected. Amounts recognised as a decrease in equity for distributions on Additional Tier One Capital are treated as expense, and increases as income, in computing GloBE Income.", topics: ["insurance", "policyholder", "additional tier one", "at1", "3.2.9"], electionIds: ["SETR_INS"], href: "/globe-income" }),
  p({ id: "LP-MR-3.3", sourceId: MR, ref: "Art. 3.3.1–3.3.6", heading: "International Shipping Income exclusion", text: "A Constituent Entity's International Shipping Income and Qualified Ancillary International Shipping Income are excluded from GloBE Income, provided the strategic or commercial management of all the ships concerned is effectively carried on from the jurisdiction where the entity is located. Ancillary income is excluded only up to 50% of the group's International Shipping Income in the jurisdiction. Costs attributable to the excluded income are excluded from GloBE Income, and the related Covered Taxes and SBIE payroll and tangible assets are removed as well.", topics: ["shipping", "international shipping income", "ancillary", "50%", "management test", "3.3"], ruleIds: ["OECD-SHIP-34"], electionIds: ["SETR_SHIP"], href: "/globe-income", note: "GMT24 rule id OECD-SHIP-34 and some screen text cite 'Art. 3.4'. In the Model Rules the shipping exclusion is Art. 3.3; Art. 3.4 allocates income between a Main Entity and its Permanent Establishment." }),
  p({ id: "LP-MR-3.4", sourceId: MR, ref: "Art. 3.4.1–3.4.5", heading: "Allocation of income between a Main Entity and a Permanent Establishment", text: "A Permanent Establishment's Financial Accounting Net Income or Loss is the amount reflected in its separate financial accounts, or the amount that would be reflected if it prepared standalone accounts under the UPE's accounting standard, adjusted to the income and expense attributable to it under the applicable tax treaty or domestic law (or, for a stateless PE, its own accounts). That amount is not taken into account for the Main Entity — except that a PE's GloBE Loss is treated as an expense of the Main Entity where the loss is deductible against the Main Entity's domestic taxable income, with later PE income recaptured to the Main Entity until offset.", topics: ["permanent establishment", "main entity", "branch", "pe loss", "3.4"], electionIds: ["SETR_PE"], instrumentIds: ["dgtopuptax3"], gapIds: ["G-SITUS"], href: "/entities" }),
  p({ id: "LP-MR-3.5", sourceId: MR, ref: "Art. 3.5.1–3.5.4", heading: "Flow-through Entities", text: "The Financial Accounting Net Income or Loss of a Flow-through Entity is reduced by the amount allocable to owners that are not Group Entities. What remains is allocated first to any Permanent Establishment through which the business is carried on; the remainder of a Tax Transparent Entity's result goes to its Constituent Entity-owners in proportion to their Ownership Interests, while a Reverse Hybrid Entity keeps its own. A Flow-through UPE follows Art. 7.1 instead.", topics: ["flow-through", "tax transparent", "reverse hybrid", "partnership", "3.5"], instrumentIds: ["dgtopuptax3"], gapIds: ["G-SITUS"], href: "/entities" }),

  /* ------------------------------------------------------------ Chapter 4 */
  p({ id: "LP-MR-4.1", sourceId: MR, ref: "Art. 4.1.1–4.1.4", heading: "Adjusted Covered Taxes", text: "Adjusted Covered Taxes are the current tax expense accrued in Financial Accounting Net Income or Loss in respect of Covered Taxes, increased by Covered Taxes recorded outside the tax line, Qualified Refundable Tax Credits recorded as a reduction of current tax, Covered Taxes paid on Uncertain Tax Positions when paid and Non-Qualified Refundable Tax Credits, and decreased by current tax on income excluded from GloBE Income, Non-Qualified Refundable Tax Credits not recorded as a reduction of tax, Covered Taxes refunded or credited, current tax on Uncertain Tax Positions and current tax not expected to be paid within three years; plus the Total Deferred Tax Adjustment Amount and Covered Taxes in equity or OCI on items included in GloBE Income.", topics: ["covered taxes", "adjusted covered taxes", "current tax", "uncertain tax position", "three years", "4.1"], gapIds: ["G-CT"], href: "/covered-taxes" }),
  p({ id: "LP-MR-4.1.5", sourceId: MR, ref: "Art. 4.1.5 · Art. 5.4", heading: "Negative Adjusted Covered Taxes in a year with no Net GloBE Income", text: "Where a jurisdiction has no Net GloBE Income for the year and its Adjusted Covered Taxes are negative and less than the Expected Adjusted Covered Taxes Amount (Net GloBE Loss multiplied by the Minimum Rate), the difference is Additional Current Top-up Tax for the year, allocated among the Constituent Entities under Art. 5.4.3. No ETR is computed in a loss year; the charge is rate-independent.", topics: ["4.1.5", "acttt", "additional current top-up", "loss year", "expected adjusted covered taxes", "negative tax"], ruleIds: ["OECD-GloBE-15"], href: "/covered-taxes" }),
  p({ id: "LP-MR-4.2", sourceId: MR, ref: "Art. 4.2.1–4.2.2", heading: "Covered Taxes — definition and exclusions", text: "Covered Taxes are taxes recorded in a Constituent Entity's accounts on its income or profits or its share of the income of another Constituent Entity; taxes on distributed profits, deemed distributions and non-business expenses under an Eligible Distribution Tax System; taxes imposed in lieu of a generally applicable corporate income tax; and taxes on retained earnings and corporate equity. Excluded are Top-up Tax under a Qualified IIR, QDMTT or UTPR, Disqualified Refundable Imputation Taxes, and taxes paid by an insurance company on returns to policyholders.", topics: ["covered taxes", "definition", "imputation tax", "in lieu of", "retained earnings", "4.2"], instrumentIds: ["dgtopuptax2"], gapIds: ["G-CT"], href: "/covered-taxes" }),
  p({ id: "LP-MR-4.3", sourceId: MR, ref: "Art. 4.3.2–4.3.4", heading: "Allocation of Covered Taxes between Constituent Entities", text: "Covered Taxes on the income of a Permanent Establishment are allocated to the PE; taxes of a Tax Transparent Entity's owners on its income are allocated to the entity; taxes charged to an owner under a CFC regime are allocated to the CFC; taxes of an owner on a Hybrid Entity's income are allocated to the hybrid; and taxes on distributions are allocated to the distributing entity. Covered Taxes on Passive Income allocated to a CFC or Hybrid Entity are capped at the lesser of the actual tax and the Top-up Tax Percentage multiplied by that Passive Income.", topics: ["cfc", "allocation", "permanent establishment", "hybrid", "passive income", "4.3"], ruleIds: ["OECD-CT-43"], href: "/covered-taxes" }),
  p({ id: "LP-MR-4.4.1", sourceId: MR, ref: "Art. 4.4.1", heading: "Total Deferred Tax Adjustment Amount — recast at the Minimum Rate", text: "The Total Deferred Tax Adjustment Amount is the deferred tax expense accrued in the accounts for Covered Taxes, recast at the Minimum Rate where the applicable domestic rate exceeds 15%, and excluding: deferred tax on items excluded from GloBE Income; Disallowed Accruals and Unclaimed Accruals; the effect of valuation adjustments and accounting-recognition adjustments on deferred tax assets; remeasurement for a change in domestic tax rate; and deferred tax on the generation and use of tax credits.", topics: ["deferred tax", "recast", "15%", "4.4.1", "valuation allowance", "tax credits"], ruleIds: ["OECD-DT-441"], gapIds: ["G-CT"], href: "/deferred-tax" }),
  p({ id: "LP-MR-4.4.2-3", sourceId: MR, ref: "Art. 4.4.2–4.4.3", heading: "Additions to the Total Deferred Tax Adjustment Amount; loss DTA below the Minimum Rate", text: "The Total Deferred Tax Adjustment Amount is increased by Disallowed Accruals and Unclaimed Accruals paid during the year, and by recaptured deferred tax liabilities paid during the year. A deferred tax asset recorded at a rate below the Minimum Rate that is attributable to a GloBE Loss may be recast at the Minimum Rate in the year the loss arises, with the resulting increase reducing the Total Deferred Tax Adjustment Amount.", topics: ["deferred tax", "4.4.2", "4.4.3", "disallowed accrual", "unclaimed accrual", "loss dta"], ruleIds: ["OECD-DT-442", "OECD-DT-443"], href: "/deferred-tax" }),
  p({ id: "LP-MR-4.4.4", sourceId: MR, ref: "Art. 4.4.4", heading: "Five-year recapture of deferred tax liabilities", text: "A deferred tax liability that was included in Adjusted Covered Taxes, is not a Recapture Exception Accrual, and is not paid or reversed by the end of the fifth Fiscal Year after the year in which it arose, is recaptured: the outstanding amount is treated as a reduction of Covered Taxes in the year it arose, and the ETR and Top-up Tax of that origin year are recomputed under Art. 5.4.1.", topics: ["recapture", "dtl", "4.4.4", "five-year", "recompute"], ruleIds: ["OECD-DT-444"], electionIds: ["OECD_4.4.7_a", "OECD_4.4.7_5"], href: "/deferred-tax" }),
  p({ id: "LP-MR-4.4.5", sourceId: MR, ref: "Art. 4.4.5", heading: "Recapture Exception Accruals", text: "Deferred tax liabilities are exempt from recapture where they relate to: cost recovery allowances on tangible assets; the cost of a licence or similar arrangement from a government for the use of immovable property or exploitation of natural resources involving significant tangible-asset investment; research and development expenses; decommissioning and remediation expenses; fair value accounting on unrealised net gains; foreign currency exchange net gains; insurance reserves and deferred acquisition costs; gains on the sale of tangible property located in the jurisdiction reinvested in tangible property there; and changes in accounting principle affecting the foregoing.", topics: ["recapture exception", "4.4.5", "tangible", "r&d", "decommissioning", "fair value", "fx"], ruleIds: ["OECD-DT-445"], href: "/deferred-tax" }),
  p({ id: "LP-MR-4.4.7", sourceId: MR, ref: "Art. 4.4.7", heading: "Disallowed Accrual and Unclaimed Accrual", text: "A Disallowed Accrual is a movement in deferred tax expense relating to an Uncertain Tax Position or to distributions from a Constituent Entity. An Unclaimed Accrual is an increase in a deferred tax liability that is not expected to be paid within five years and that the Filing Constituent Entity annually elects not to include in the Total Deferred Tax Adjustment Amount, so that it is never subject to recapture and counts only when paid.", topics: ["unclaimed accrual", "disallowed accrual", "4.4.7", "annual election", "uncertain tax position"], electionIds: ["OECD_4.4.7_a"], ruleIds: ["OECD-DT-442"], href: "/deferred-tax" }),
  p({ id: "LP-MR-4.5", sourceId: MR, ref: "Art. 4.5.1–4.5.6", heading: "GloBE Loss Election", text: "In lieu of the Art. 4.4 deferred-tax mechanics, the Filing Constituent Entity may elect for a jurisdiction to establish a GloBE Loss Deferred Tax Asset equal to the Net GloBE Loss multiplied by the Minimum Rate. The asset is carried forward and used in any later year with Net GloBE Income, adding the used amount to Adjusted Covered Taxes. The election must be filed with the first GloBE Information Return for the jurisdiction; if revoked, the remaining asset is reduced to zero and the election cannot be re-made for that jurisdiction.", topics: ["globe loss election", "4.5", "deferred tax asset", "first gir", "revocation"], electionIds: ["OECD_4.5", "SETR_4.5"], href: "/deferred-tax" }),
  p({ id: "LP-MR-4.6", sourceId: MR, ref: "Art. 4.6.1–4.6.4", heading: "Post-filing adjustments and rate changes", text: "An increase in Covered Taxes for a prior year is treated as an adjustment in the current year; a decrease requires the prior year's ETR and Top-up Tax to be recomputed, unless the Filing Constituent Entity makes an Annual Election to treat an immaterial decrease — aggregate decreases below EUR 1 million for the jurisdiction — in the current year. Deferred tax remeasured for a rate reduction below the Minimum Rate is adjusted; current tax expense above EUR 1 million that is not paid within three years of the year end triggers a recomputation of that year.", topics: ["post-filing", "prior year", "immaterial", "eur 1 million", "4.6", "rate change", "unpaid tax"], electionIds: ["OECD_4.6.1", "SETR_PYE"], href: "/covered-taxes" }),

  /* ------------------------------------------------------------ Chapter 5 */
  p({ id: "LP-MR-5.1", sourceId: MR, ref: "Art. 5.1.1–5.1.3", heading: "Jurisdictional Effective Tax Rate", text: "The ETR of an MNE Group for a jurisdiction with Net GloBE Income is the sum of the Adjusted Covered Taxes of each Constituent Entity located there divided by the Net GloBE Income of the jurisdiction — the excess of the GloBE Income of all Constituent Entities over their GloBE Losses. Investment Entities are computed separately under Art. 7.4, and Joint Venture Groups and Minority-Owned Constituent Entities are also blended separately.", topics: ["etr", "effective tax rate", "jurisdictional blending", "net globe income", "5.1"], ruleIds: ["OECD-GloBE-15"], instrumentIds: ["dgtopuptax8"], gapIds: ["G-ETR"], href: "/etr", note: "GMT24 rule id OECD-MOCE-513 cites 'Art. 5.1.3'; the Minority-Owned Constituent Entity rule is Art. 5.6 in the Model Rules." }),
  p({ id: "LP-MR-5.2", sourceId: MR, ref: "Art. 5.2.1–5.2.5", heading: "Top-up Tax Percentage, Excess Profit and Jurisdictional Top-up Tax", text: "The Top-up Tax Percentage is the positive difference between the Minimum Rate of 15% and the jurisdiction's ETR. Excess Profit is Net GloBE Income less the Substance-based Income Exclusion. Jurisdictional Top-up Tax is the Top-up Tax Percentage multiplied by Excess Profit, plus any Additional Current Top-up Tax, less any Qualified Domestic Minimum Top-up Tax payable for the year. It is allocated to each Constituent Entity in proportion to its GloBE Income.", topics: ["top-up tax", "excess profit", "minimum rate", "15%", "qdmtt credit", "5.2"], ruleIds: ["OECD-GloBE-15", "OECD-ENTE-521"], gapIds: ["G-ETR", "G-ORDER"], href: "/top-up" }),
  p({ id: "LP-MR-5.3", sourceId: MR, ref: "Art. 5.3.1–5.3.7", heading: "Substance-based Income Exclusion", text: "Unless the Filing Constituent Entity elects annually not to apply it, the Substance-based Income Exclusion for a jurisdiction is the sum of the payroll carve-out and the tangible asset carve-out of each Constituent Entity other than Investment Entities. The payroll carve-out is 5% of Eligible Payroll Costs of Eligible Employees performing activities for the group in the jurisdiction — excluding costs capitalised into the carrying value of Eligible Tangible Assets and costs attributable to excluded International Shipping Income. The tangible asset carve-out is 5% of the carrying value, averaged over the beginning and end of the year, of property, plant and equipment, natural resources, a lessee's right of use of tangible assets and government licences for the use of immovable property or exploitation of natural resources located in the jurisdiction — excluding property held for sale, lease or investment and shipping assets. PE and flow-through attributions follow Art. 5.3.6–5.3.7. The transitional rates are in Art. 9.2.", topics: ["sbie", "substance", "payroll", "tangible assets", "carve-out", "5.3", "eligible employees", "right of use"], ruleIds: ["OECD-SBIE-2026"], electionIds: ["OECD_5.3.1"], instrumentIds: ["dgtopuptax4"], gapIds: ["G-SBIE"], href: "/sbie" }),
  p({ id: "LP-MR-5.4", sourceId: MR, ref: "Art. 5.4.1–5.4.4", heading: "Additional Current Top-up Tax", text: "Where a recalculation under Art. 4.4.4, 4.6, 5.3.4 or 7.3 increases a prior year's Top-up Tax, the increase is Additional Current Top-up Tax of the current year and is allocated to Constituent Entities in proportion to their GloBE Income in the recalculated year. In a year with no Net GloBE Income, Additional Current Top-up Tax arising under Art. 4.1.5 is allocated to the entities with Adjusted Covered Taxes below zero and below their Expected Adjusted Covered Taxes; for the purpose of Chapter 2, an entity allocated such tax is treated as a Low-Taxed Constituent Entity.", topics: ["additional current top-up", "recalculation", "5.4", "prior year", "acttt"], ruleIds: ["OECD-GloBE-15", "OECD-DT-444"], href: "/top-up" }),
  p({ id: "LP-MR-5.5", sourceId: MR, ref: "Art. 5.5.1–5.5.3", heading: "De minimis exclusion", text: "At the Annual Election of the Filing Constituent Entity, the Top-up Tax of the Constituent Entities in a jurisdiction is deemed to be zero where the Average GloBE Revenue of the jurisdiction is less than EUR 10 million and the Average GloBE Income is a loss or less than EUR 1 million, averaging the current and the two preceding Fiscal Years. Investment Entities and stateless entities are left out of the test.", topics: ["de minimis", "eur 10 million", "eur 1 million", "5.5", "annual election"], electionIds: ["OECD_5.5"], href: "/safe-harbours" }),
  p({ id: "LP-MR-5.6", sourceId: MR, ref: "Art. 5.6.1–5.6.2 · Art. 10.1 'Minority-Owned Constituent Entity'", heading: "Minority-Owned Constituent Entities", text: "A Minority-Owned Constituent Entity is one in which the UPE holds, directly or indirectly, an Ownership Interest of 30% or less. The members of a Minority-Owned Subgroup — a Minority-Owned Parent Entity and its Minority-Owned Subsidiaries — compute their ETR and Top-up Tax as if they were a separate MNE Group; a Minority-Owned Constituent Entity that is not part of such a subgroup is computed on its own. Neither is blended with the majority-owned entities in the same jurisdiction.", topics: ["moce", "minority-owned", "30%", "mosg", "separate etr", "5.6"], ruleIds: ["OECD-MOCE-513"], instrumentIds: ["dgtopuptax8"], gapIds: ["G-SITUS"], href: "/entities" }),

  /* ------------------------------------------------------------ Chapter 6 */
  p({ id: "LP-MR-6.1-6.2", sourceId: MR, ref: "Art. 6.1–6.2", heading: "Mergers, demergers, and entities joining or leaving a group", text: "After a merger the EUR 750 million test is applied to the combined revenue of the merging groups; after a demerger each resulting group is tested with special rules for the first four years. An Entity that becomes or ceases to be a Constituent Entity during a year is treated as a member of the group for that year if any part of its results are consolidated line by line; its GloBE Income, Covered Taxes, deferred tax attributes and SBIE inputs are taken into account for the period of membership, and its assets and liabilities keep their historical carrying values unless Art. 6.3 applies.", topics: ["merger", "demerger", "acquisition", "joining", "leaving", "6.1", "6.2"], ruleIds: ["OECD-C6-61"], href: "/entities" }),
  p({ id: "LP-MR-6.3", sourceId: MR, ref: "Art. 6.3.1–6.3.4", heading: "Transfers of assets and liabilities; GloBE Reorganisations; Art. 6.3.4 election", text: "On a disposition of assets and liabilities the disposing Constituent Entity includes the gain or loss in GloBE Income and the acquiring entity takes the acquirer's carrying value under the UPE's standard. In a GloBE Reorganisation the disposing entity excludes the gain or loss (except Non-qualifying Gain or Loss) and the acquirer carries over the disposing entity's carrying values. Where a Constituent Entity is required or permitted to adjust the basis of its assets and liabilities to fair value for domestic tax purposes, it may elect to recognise the resulting gain or loss in GloBE Income and use fair value as the GloBE carrying value — either wholly in the triggering year or spread evenly over that year and the four following years.", topics: ["reorganisation", "transfer", "fair value", "step-up", "6.3.4", "election", "spread"], ruleIds: ["OECD-C6-61"], electionIds: ["OECD_6.3.4", "OECD_6.3.4c"], href: "/globe-income" }),
  p({ id: "LP-MR-6.4", sourceId: MR, ref: "Art. 6.4.1–6.4.2 · Art. 10.1 'Joint Venture'", heading: "Joint Ventures", text: "A Joint Venture is an Entity whose financial results are reported under the equity method in the UPE's consolidated financial statements and in which the UPE holds, directly or indirectly, at least 50% of the Ownership Interests (excluding UPEs of in-scope groups, Excluded Entities and certain Investment Entities). The Joint Venture and its JV Subsidiaries — the JV Group — compute Top-up Tax as if they were Constituent Entities of a separate MNE Group with the JV as UPE. Each Parent Entity brings its Allocable Share of the JV Group's Top-up Tax into charge under the IIR, and any residual falls into the Total UTPR Top-up Tax Amount.", topics: ["joint venture", "jv", "equity method", "50%", "6.4"], ruleIds: ["OECD-JV-64"], href: "/entities" }),
  p({ id: "LP-MR-6.5", sourceId: MR, ref: "Art. 6.5", heading: "Multi-Parented MNE Groups", text: "Where two or more groups are combined through a Stapled Structure or a Dual-listed Arrangement, the Entities of the combined groups are treated as members of a single MNE Group; the UPEs each apply the IIR to their Allocable Share, and a single GloBE Information Return covers the whole group unless the UPEs agree otherwise.", topics: ["multi-parented", "stapled", "dual-listed", "6.5"], href: "/group" }),

  /* ------------------------------------------------------------ Chapter 7 */
  p({ id: "LP-MR-7.1-7.2", sourceId: MR, ref: "Art. 7.1–7.2", heading: "Flow-through UPE and Deductible Dividend Regimes", text: "A UPE that is a Flow-through Entity reduces its GloBE Income by the amount attributable to holders of Ownership Interests who are taxed on it at or above the Minimum Rate within twelve months, or who are individuals or Excluded Entities resident in the UPE's jurisdiction. A UPE subject to a Deductible Dividend Regime reduces its GloBE Income by dividends distributed within twelve months of year end that are taxed in the recipient's hands at or above the Minimum Rate, or paid to qualifying recipients. Covered Taxes are reduced proportionately.", topics: ["flow-through upe", "deductible dividend", "cooperative", "7.1", "7.2"], href: "/entities" }),
  p({ id: "LP-MR-7.3", sourceId: MR, ref: "Art. 7.3.1–7.3.8", heading: "Eligible Distribution Tax Systems election", text: "For Constituent Entities located in a jurisdiction with an Eligible Distribution Tax System, the Filing Constituent Entity may make an Annual Election to include a Deemed Distribution Tax in Adjusted Covered Taxes — the lesser of the amount needed to lift the ETR to the Minimum Rate and the tax that would have been due had the profits been distributed. The amount is tracked in a Deemed Distribution Tax Recapture Account; any balance not settled by actual distribution taxes within four years reduces Covered Taxes of the origin year and is recaptured under Art. 5.4.", topics: ["distribution tax", "edts", "estonia", "deemed distribution", "recapture account", "7.3"], electionIds: ["OECD_7.3"], href: "/covered-taxes" }),
  p({ id: "LP-MR-7.4", sourceId: MR, ref: "Art. 7.4.1–7.4.6", heading: "Investment Entities — separate ETR", text: "The ETR of an Investment Entity is computed separately from the ETR of the jurisdiction: the entity's Adjusted Covered Taxes divided by the group's Allocable Share of its GloBE Income, excluding the share attributable to non-group owners. Top-up Tax is the Top-up Tax Percentage multiplied by the Allocable Share of GloBE Income less any Substance-based Income Exclusion attributable to that share. Where several Investment Entities are located in the same jurisdiction they are blended together.", topics: ["investment entity", "separate etr", "7.4", "allocable share"], ruleIds: ["OECD-IE-75"], instrumentIds: ["dgtopuptax8"], href: "/entities" }),
  p({ id: "LP-MR-7.5-7.6", sourceId: MR, ref: "Art. 7.5–7.6", heading: "Investment Entity tax transparency and taxable distribution method elections", text: "A Filing Constituent Entity may make a Five-Year Election to treat an Investment Entity or Insurance Investment Entity as a Tax Transparent Entity where its Constituent Entity-owner is taxed on fair-value or similar changes in its interest at a rate at or above the Minimum Rate. Alternatively, a Five-Year Election may apply the Taxable Distribution Method: distributions and deemed distributions are included in the owner's GloBE Income, and undistributed GloBE Income remaining after the third year is charged to the Investment Entity at the Minimum Rate.", topics: ["investment entity", "transparency election", "taxable distribution", "7.5", "7.6", "five-year"], ruleIds: ["OECD-IE-75"], electionIds: ["OECD_7.5", "OECD_7.6"], href: "/entities" }),

  /* ------------------------------------------------------------ Chapter 8 */
  p({ id: "LP-MR-8.1", sourceId: MR, ref: "Art. 8.1.1–8.1.6", heading: "GloBE Information Return — filing obligation and deadline", text: "Each Constituent Entity files a GloBE Information Return with the tax administration of its jurisdiction, unless a Designated Local Entity files on behalf of the local entities, or the UPE or a Designated Filing Entity files in a jurisdiction that has a Qualifying Competent Authority Agreement in effect with the Constituent Entity's jurisdiction for the year. The return identifies the group, its structure and the information needed to compute the ETR, Top-up Tax and its allocation, and the elections made. It is due within 15 months after the last day of the Reporting Fiscal Year (18 months for the Transition Year under Art. 9.4).", topics: ["gir", "globe information return", "filing", "15 months", "designated filing entity", "qcaa", "8.1"], ruleIds: ["OECD-GIR-XML"], instrumentIds: ["s53-57"], gapIds: ["G-FILE"], href: "/gir" }),
  p({ id: "LP-MR-8.2", sourceId: MR, ref: "Art. 8.2", heading: "Safe harbours", text: "At the election of the Filing Constituent Entity, the Top-up Tax for the Constituent Entities located in a jurisdiction is deemed to be zero for a Fiscal Year where the group demonstrates that it qualifies for a GloBE Safe Harbour agreed by the Inclusive Framework for that jurisdiction. The Rules themselves do not set the safe-harbour conditions; they are in the Safe Harbours and Penalty Relief document and later Administrative Guidance.", topics: ["safe harbour", "8.2", "deemed zero"], ruleIds: ["OECD-TCSH-2026", "OECD-SETR-SH", "OECD-SBTISH"], electionIds: ["SH_TCSH", "SH_QDMTT"], href: "/safe-harbours" }),

  /* ------------------------------------------------------------ Chapter 9 */
  p({ id: "LP-MR-9.1", sourceId: MR, ref: "Art. 9.1.1–9.1.3", heading: "Tax attributes upon transition", text: "In the Transition Year the group takes into account the deferred tax assets and liabilities reflected in the accounts of each Constituent Entity at the start of the year, at the lower of the Minimum Rate and the domestic rate (a loss DTA recorded below the Minimum Rate may be taken at the Minimum Rate). Deferred tax assets arising from items excluded from GloBE Income in transactions after 30 November 2021 are excluded. For assets transferred between Constituent Entities after 30 November 2021 and before the Transition Year (other than inventory), the acquirer uses the disposing entity's carrying value.", topics: ["transition", "9.1", "opening deferred tax", "30 november 2021", "carrying value", "transfer"], ruleIds: ["OECD-TR-91"], electionIds: ["OECD_9.1.3"], href: "/deferred-tax" }),
  p({ id: "LP-MR-9.2", sourceId: MR, ref: "Art. 9.2.1–9.2.2", heading: "Transitional Substance-based Income Exclusion rates", text: "For the purposes of Art. 5.3.3 the payroll rate and for Art. 5.3.4 the tangible asset rate are, by the year the Fiscal Year begins: 2023 — 10.0% / 8.0%; 2024 — 9.8% / 7.8%; 2025 — 9.6% / 7.6%; 2026 — 9.4% / 7.4%; 2027 — 9.2% / 7.2%; 2028 — 9.0% / 7.0%; 2029 — 8.2% / 6.6%; 2030 — 7.4% / 6.2%; 2031 — 6.6% / 5.8%; 2032 — 5.8% / 5.4%. From Fiscal Years beginning in 2033 both rates are 5%.", topics: ["sbie", "transitional rates", "9.2", "9.4%", "7.4%", "step-down"], ruleIds: ["OECD-SBIE-2026", "TH-SBIE-MOF-1"], instrumentIds: ["moftopuptax1"], gapIds: ["G-SBIE"], href: "/sbie" }),
  p({ id: "LP-MR-9.3", sourceId: MR, ref: "Art. 9.3", heading: "Transitional exclusion from the UTPR — initial phase of international activity", text: "The UTPR Top-up Tax Amount of the UPE jurisdiction is reduced to zero for the first five years of an MNE Group's initial phase of international activity: years in which the group has Constituent Entities in no more than six jurisdictions and the Net Book Value of Tangible Assets of all entities outside the Reference Jurisdiction does not exceed EUR 50 million. The five years run from the first day of the first year the group comes within scope.", topics: ["utpr", "initial phase", "five years", "six jurisdictions", "eur 50 million", "9.3"], ruleIds: ["OECD-UTPR-26"], href: "/allocation" }),
  p({ id: "LP-MR-9.4", sourceId: MR, ref: "Art. 9.4", heading: "Transitional relief for filing obligations", text: "For the Transition Year — the first Fiscal Year in which the MNE Group comes within scope of the GloBE Rules in a jurisdiction — the GloBE Information Return and notifications are due within 18 months after the last day of the Reporting Fiscal Year instead of 15.", topics: ["18 months", "transition year", "filing deadline", "9.4"], ruleIds: ["OECD-GIR-XML"], gapIds: ["G-FILE"], href: "/gir" }),

  /* ----------------------------------------------------------- Chapter 10 */
  p({ id: "LP-MR-10.1", sourceId: MR, ref: "Art. 10.1 — selected definitions", heading: "Minimum Rate, Low-Taxed Constituent Entity, Qualified IIR / UTPR / QDMTT", text: "The Minimum Rate is 15%. A Low-Taxed Constituent Entity is a Constituent Entity located in a Low-Tax Jurisdiction — one where the group's jurisdictional ETR is below the Minimum Rate — or a stateless entity with GloBE Income taxed below it. A Qualified IIR, Qualified UTPR and Qualified Domestic Minimum Top-up Tax are domestic rules that are equivalent to the GloBE Rules (or, for a QDMTT, that compute Excess Profits in the jurisdiction in a manner equivalent to the Rules and raise the domestic tax to the Minimum Rate) and are implemented and administered consistently with the Rules and Commentary, without providing related benefits.", topics: ["minimum rate", "15%", "definitions", "qualified iir", "qualified utpr", "qdmtt", "low-taxed", "10.1"], ruleIds: ["OECD-GloBE-15", "TH-QDMTT-2025", "IE-QDMTT-2024", "JP-IIR-2024"], href: "/rulebook" }),
  p({ id: "LP-MR-10.3", sourceId: MR, ref: "Art. 10.3.1–10.3.6", heading: "Location of an Entity or Permanent Establishment", text: "An Entity other than a Flow-through Entity is located where it is tax resident by place of management, creation or similar criteria; otherwise where it was created. A Flow-through Entity is stateless unless it is the UPE or is required to apply a Qualified IIR, in which case it is located where it was created. A Permanent Establishment is located where it is treated as such under the applicable treaty, where it is taxed on a net basis under domestic law, where the business is carried on for a PE in a jurisdiction without a corporate income tax, or is stateless otherwise. An Entity resident in two jurisdictions is placed by the treaty tie-breaker; failing that, by the greater Covered Taxes, then the greater SBIE, then treated as stateless (or located where created if it is the UPE).", topics: ["location", "tax residence", "dual resident", "stateless", "tie-breaker", "10.3", "permanent establishment"], instrumentIds: ["dgtopuptax3", "dgtopuptax8"], gapIds: ["G-SITUS"], href: "/entities" }),

  /* ------------------------------------------------- Administrative Guidance */
  p({ id: "LP-AG23-02-2.2", sourceId: "OECD-AG-2023-02", ref: "§2.2 — Excluded Equity Gain or Loss and net investment hedges", heading: "Net investment hedge election", text: "A Filing Constituent Entity may make a Five-Year Election to treat foreign exchange gains and losses on a hedging instrument as Excluded Equity Gain or Loss, where the instrument hedges currency risk on Ownership Interests other than Portfolio Shareholdings, the hedge is accounted for as a net investment hedge of a foreign operation, and the gain or loss would otherwise be reflected in GloBE Income. The election aligns the hedge with the excluded item it protects.", effectiveFrom: "2023-02-02", topics: ["hedge", "net investment", "fx", "excluded equity", "election"], electionIds: ["OECD_3.2.1c_fx"], href: "/globe-income" }),
  p({ id: "LP-AG23-02-2.4", sourceId: "OECD-AG-2023-02", ref: "§2.4 — Debt release", heading: "Debt release election", text: "A Filing Constituent Entity may make an Annual Election to exclude debt-release income from GloBE Income where the release occurs in statutory insolvency or bankruptcy proceedings, or where the debtor would reasonably be expected to be insolvent within twelve months but for the release of third-party debt, or — for related-party debt — to the extent the debtor's liabilities exceed the fair value of its assets immediately before the release, capped at the lesser of the reduction in tax attributes and that excess.", effectiveFrom: "2023-02-02", topics: ["debt release", "insolvency", "forgiveness", "annual election"], electionIds: ["OECD_3.2.1_debt"], href: "/globe-income" }),
  p({ id: "LP-AG23-02-2.7", sourceId: "OECD-AG-2023-02", ref: "§2.7 — Excess Negative Tax Expense", heading: "Excess Negative Tax Expense administrative procedure", text: "Where a jurisdiction has positive Net GloBE Income but negative Adjusted Covered Taxes, the negative amount is excluded from the ETR computation for the year — so the ETR is 0% and the Top-up Tax Percentage cannot exceed the Minimum Rate — and is carried forward as Excess Negative Tax Expense, reducing Adjusted Covered Taxes in subsequent years until exhausted. The procedure is mandatory in that situation. Where the jurisdiction has a Net GloBE Loss and Art. 4.1.5 would otherwise produce Additional Current Top-up Tax, the Filing Constituent Entity may instead elect to carry the excess forward the same way.", effectiveFrom: "2023-02-02", topics: ["ente", "excess negative tax expense", "negative covered tax", "carry-forward", "election", "4.1.5"], ruleIds: ["OECD-ENTE-521", "OECD-GloBE-15"], electionIds: ["OECD_4.1.5"], href: "/etr" }),
  p({ id: "LP-AG23-02-2.9", sourceId: "OECD-AG-2023-02", ref: "§2.9 — Equity Investment Inclusion Election", heading: "Equity Investment Inclusion Election", text: "A Filing Constituent Entity may make a Five-Year Election for a jurisdiction to include in GloBE Income the gains, losses and equity-method results on Ownership Interests that would otherwise be Excluded Equity Gain or Loss (other than Qualified Ownership Interests in flow-through structures held for tax credits), together with the related current and deferred Covered Taxes. The election applies to all Constituent Entities in the jurisdiction; on revocation, losses previously included are recaptured against later gains.", effectiveFrom: "2023-02-02", topics: ["equity investment", "inclusion election", "excluded equity", "five-year"], electionIds: ["OECD_3.2.1c_eq"], href: "/globe-income" }),
  p({ id: "LP-AG23-02-5", sourceId: "OECD-AG-2023-02", ref: "Ch. 5 — Qualified Domestic Minimum Top-up Taxes", heading: "QDMTT design standards", text: "A domestic minimum top-up tax is qualified where it computes the Excess Profits of the Constituent Entities located in the jurisdiction in a manner equivalent to the GloBE Rules, using the UPE's consolidated accounting standard (or a local standard where all local entities use it and no group entity has a material distortion), taxes them at the Minimum Rate on the same jurisdictional basis, and is implemented and administered consistently with the Rules and Commentary. A QDMTT need not provide the SBIE or de minimis exclusion, may compute in local currency, and must not exclude pushed-down CFC or PE taxes in ways that would raise the QDMTT above the GloBE Top-up Tax. A QDMTT payable reduces the jurisdiction's GloBE Top-up Tax to zero under Art. 5.2.3.", effectiveFrom: "2023-02-02", topics: ["qdmtt", "domestic minimum tax", "design", "accounting standard", "local currency", "credit"], ruleIds: ["TH-QDMTT-2025", "IE-QDMTT-2024"], electionIds: ["OECD_QDMTT_FX"], instrumentIds: ["prk2567"], gapIds: ["G-ORDER", "G-GAAP"], href: "/thailand/liability" }),
  p({ id: "LP-AG23-07-2", sourceId: "OECD-AG-2023-07", ref: "Ch. 2 — Tax credits", heading: "Marketable Transferable Tax Credits", text: "A Marketable Transferable Tax Credit — one that is legally transferable to an unrelated party and traded, or would trade, at or above 80% of its net present value within 15 months of the origination year — is treated as income in GloBE Income for the originating entity, like a Qualified Refundable Tax Credit. Other transferable credits and non-refundable credits reduce Covered Taxes. A purchaser treats the credit's face value less purchase price as income when used.", effectiveFrom: "2023-07-17", topics: ["mttc", "transferable tax credit", "80%", "incentive", "qrtc"], electionIds: ["SETR_QRTC"], gapIds: ["G-BOI"], href: "/incentives" }),
  p({ id: "LP-AG23-07-3", sourceId: "OECD-AG-2023-07", ref: "Ch. 3 — Currency conversion", heading: "Currency conversion in the GloBE computation", text: "GloBE computations are performed in the presentation currency of the UPE's consolidated financial statements; local-currency amounts are converted using the rates applied in preparing those statements. EUR thresholds in the Rules are converted at the average foreign exchange rate of the European Central Bank for December of the preceding year (or the average of the rates published by the local central bank where the ECB publishes none). A QDMTT may require computation in local currency or permit the presentation currency, subject to a Five-Year Election.", effectiveFrom: "2023-07-17", topics: ["currency", "fx", "presentation currency", "ecb", "december average", "threshold conversion"], electionIds: ["OECD_QDMTT_FX"], instrumentIds: ["dgtopuptax6"], gapIds: ["G-FX", "G-SCOPE"], href: "/fx" }),
  p({ id: "LP-AG23-07-4", sourceId: "OECD-AG-2023-07", ref: "Ch. 4 — Substance-based Income Exclusion", heading: "SBIE — interjurisdictional employees and assets, leases, impairment", text: "Eligible Payroll Costs of an employee who works in more than one jurisdiction count for the employer's jurisdiction in full where more than 50% of working time is spent there, and proportionately otherwise. Eligible Tangible Assets located in more than one jurisdiction follow the same 50% rule by time. For an operating lease, the lessor includes the excess of the asset's carrying value over the lessee's right-of-use asset; a lessee includes its right-of-use asset. Impairment losses reduce the carrying value used, and the carrying value is measured net of accumulated depreciation as reflected in the consolidated statements.", effectiveFrom: "2023-07-17", topics: ["sbie", "payroll", "50%", "lease", "right of use", "impairment", "interjurisdictional"], ruleIds: ["OECD-SBIE-2026"], instrumentIds: ["dgtopuptax4"], gapIds: ["G-SBIE"], href: "/sbie" }),
  p({ id: "LP-AG23-07-5.1", sourceId: "OECD-AG-2023-07", ref: "Ch. 5.1 — QDMTT Safe Harbour", heading: "QDMTT Safe Harbour", text: "Where a jurisdiction's QDMTT meets the QDMTT Accounting Standard, the Consistency Standard and the Administration Standard — as recorded on the Central Record — the Filing Constituent Entity may elect to treat the GloBE Top-up Tax for that jurisdiction as zero, instead of computing it and crediting the QDMTT. The safe harbour does not apply to the Excess Profits of entities that the QDMTT does not tax, such as a flow-through UPE or Investment Entities the QDMTT excludes, and does not switch off a domestic charge that the QDMTT itself imposes.", effectiveFrom: "2023-07-17", topics: ["qdmtt safe harbour", "central record", "deemed zero", "consistency standard"], ruleIds: ["TH-QDMTT-2025", "IE-QDMTT-2024"], electionIds: ["SH_QDMTT"], gapIds: ["G-ORDER"], href: "/allocation" }),
  p({ id: "LP-AG23-07-5.2", sourceId: "OECD-AG-2023-07", ref: "Ch. 5.2 — Transitional UTPR Safe Harbour", heading: "Transitional UTPR Safe Harbour", text: "The UTPR Top-up Tax Amount for the UPE jurisdiction is deemed to be zero for Fiscal Years beginning on or before 31 December 2025 and ending before 31 December 2026 where that jurisdiction applies a nominal corporate income tax rate of at least 20%. The January 2026 package extends the relief; see the Side-by-Side passages.", effectiveFrom: "2024-01-01", effectiveTo: "2026-12-30", topics: ["utpr safe harbour", "20%", "upe jurisdiction", "transitional"], ruleIds: ["US-SBS-2026"], electionIds: ["SH_UTPR"], href: "/safe-harbours" }),
  p({ id: "LP-AG23-12-1", sourceId: "OECD-AG-2023-12", ref: "Ch. 1 — Transitional CbCR Safe Harbour", heading: "TCSH — purchase price accounting, hybrid arbitrage, Qualified Financial Statements", text: "For the Transitional CbCR Safe Harbour, purchase price accounting adjustments in a Constituent Entity's Qualified Financial Statements are permitted only where the CbC report has consistently reflected them and a goodwill impairment adjustment is made to profit before tax. Qualified Financial Statements must be used consistently across all entities in a jurisdiction. A jurisdiction is not eligible for the safe harbour where a hybrid arbitrage arrangement entered into after 15 December 2022 — a deduction/non-inclusion, duplicate loss or duplicate tax recognition arrangement — has reduced its simplified income or increased its simplified covered taxes, unless the effect is reversed.", effectiveFrom: "2023-12-18", topics: ["tcsh", "purchase price accounting", "hybrid arbitrage", "15 december 2022", "qualified financial statements"], ruleIds: ["OECD-TCSH-2026"], electionIds: ["SH_TCSH", "SH_TCSH_ETR"], href: "/safe-harbours" }),
  p({ id: "LP-AG23-12-2", sourceId: "OECD-AG-2023-12", ref: "Ch. 2 — Simplified Calculations for Non-Material Constituent Entities", heading: "NMCE Simplified Calculations Safe Harbour", text: "For a Non-Material Constituent Entity — one excluded from the consolidated statements solely on size or materiality grounds and whose accounts are used for the CbC report — the Filing Constituent Entity may elect to use its CbC revenue as both GloBE Revenue and GloBE Income, and its income tax accrued as Covered Taxes, in the routine profits, de minimis and ETR tests of the Simplified Calculations Safe Harbour.", effectiveFrom: "2023-12-18", topics: ["nmce", "non-material", "simplified calculations", "cbcr"], electionIds: ["SH_NMCE", "SH_SCSH"], href: "/safe-harbours" }),
  p({ id: "LP-AG23-12-4", sourceId: "OECD-AG-2023-12", ref: "Ch. 4 — Blended CFC Tax Regimes", heading: "Allocation of tax under blended CFC regimes", text: "For Fiscal Years beginning on or before 31 December 2025 and ending before 1 July 2027, tax paid under a Blended CFC Tax Regime — one that aggregates the income of CFCs in several jurisdictions, such as GILTI — is allocated to each CFC by a key: the CFC's attributable income multiplied by (Applicable Rate less the Blended CFC Allocation Key jurisdiction's GloBE ETR), divided by the sum of that product across all CFCs. The regime's own foreign tax credit rules and the GloBE ETR feed the key.", effectiveFrom: "2023-12-18", effectiveTo: "2027-06-30", topics: ["blended cfc", "gilti", "allocation key", "cfc tax"], ruleIds: ["OECD-CT-43"], href: "/covered-taxes" }),
  p({ id: "LP-AG24-06-1", sourceId: "OECD-AG-2024-06", ref: "Ch. 1 — Deferred tax liability recapture", heading: "DTL recapture — Aggregate DTL Categories and the five-year unclaimed accrual election", text: "For recapture tracking a Constituent Entity may group deferred tax liabilities into an Aggregate DTL Category by general ledger account or balance-sheet item, applying a first-in-first-out or last-in-first-out methodology consistently to determine whether an outstanding balance has reversed within five years; Recapture Exception Accruals and swinging accounts are kept apart. A Five-Year Election allows a whole Aggregate DTL Category or account to be treated as an Unclaimed Accrual, removing it from Adjusted Covered Taxes and from recapture for that period; short-term categories that reverse within five years need no tracking.", effectiveFrom: "2024-06-17", topics: ["recapture", "aggregate dtl category", "fifo", "lifo", "unclaimed accrual", "five-year election"], ruleIds: ["OECD-DT-444", "OECD-DT-442"], electionIds: ["OECD_4.4.7_5"], href: "/deferred-tax" }),
  p({ id: "LP-AG24-06-2", sourceId: "OECD-AG-2024-06", ref: "Ch. 2 — Divergences between GloBE and accounting carrying values", heading: "Deferred tax where GloBE carrying value differs from the accounting carrying value", text: "Where the GloBE Rules prescribe a carrying value for an asset or liability that differs from the accounting carrying value — after a GloBE Reorganisation, an Art. 6.3.4 election, an Art. 9.1.3 transfer or the realisation election — deferred tax is recomputed on the GloBE carrying value so that the deferred tax expense in Adjusted Covered Taxes matches the GloBE basis, and the accounting deferred tax on the divergent amount is disregarded.", effectiveFrom: "2024-06-17", topics: ["carrying value", "divergence", "deferred tax", "globe basis", "9.1.3", "6.3.4"], ruleIds: ["OECD-TR-91", "OECD-C6-61"], electionIds: ["OECD_9.1.3", "OECD_6.3.4"], href: "/deferred-tax" }),
  p({ id: "LP-AG24-06-3", sourceId: "OECD-AG-2024-06", ref: "Ch. 3 — Allocation of cross-border current and deferred taxes", heading: "Cross-border deferred tax allocation and the election not to allocate", text: "Deferred tax expense of a Main Entity, owner or parent that relates to the income of a Permanent Establishment, Hybrid Entity, Tax Transparent Entity or CFC is allocated to that entity in the same way as current tax under Art. 4.3.2, with a substitute loss carry-forward mechanism where the owner's domestic loss absorbs the foreign income. A Filing Constituent Entity may make a Five-Year Election not to allocate deferred tax expense cross-border for a jurisdiction; the deferred tax then stays with the entity that recorded it.", effectiveFrom: "2024-06-17", topics: ["cross-border deferred tax", "allocation", "cfc", "permanent establishment", "election", "five-year"], ruleIds: ["OECD-CT-43"], electionIds: ["OECD_4_nbdt"], href: "/deferred-tax" }),
  p({ id: "LP-AG25-01-1", sourceId: "OECD-AG-2025-01", ref: "Ch. 1 — Article 9.1 deferred tax assets", heading: "Transition attributes arising from governmental arrangements and pre-transition step-ups", text: "Deferred tax assets recorded before the Transition Year that arise from a governmental arrangement concluded after 30 November 2021 — a tax basis step-up, a tax credit or a retroactive rate change granted or agreed with the government — are excluded from the Art. 9.1.1 opening attributes, subject to a grace period for arrangements reversed before the deadline. Deferred tax assets attributable to tax losses that were created by such arrangements are treated the same way. The guidance protects the transition rule from losses and basis manufactured for GloBE purposes.", effectiveFrom: "2025-01-15", topics: ["9.1", "transition", "governmental arrangement", "step-up", "deferred tax asset", "grace period"], ruleIds: ["OECD-TR-91"], electionIds: ["OECD_9.1.3"], href: "/deferred-tax" }),

  /* --------------------------------------------- Safe harbours & 2026 package */
  p({ id: "LP-SH22-1", sourceId: "OECD-SH-2022-12", ref: "Ch. 1 — Transitional CbCR Safe Harbour", heading: "Transitional CbCR Safe Harbour — three tests, transition period, once out always out", text: "During the Transition Period the Top-up Tax for a jurisdiction is deemed to be zero where, on the group's Qualified CbC Report and Qualified Financial Statements, the jurisdiction passes any one of three tests: de minimis — Total Revenue below EUR 10 million and Profit (Loss) before Income Tax below EUR 1 million; simplified ETR — Simplified Covered Taxes divided by Profit before Income Tax at or above the Transition Rate of 15% for Fiscal Years beginning in 2023 and 2024, 16% for 2025 and 17% for 2026; or routine profits — Profit before Income Tax at or below the Substance-based Income Exclusion amount. A jurisdiction that did not apply the safe harbour in a year in which the group was subject to the Rules cannot apply it in a later year. As issued, the Transition Period covered Fiscal Years beginning on or before 31 December 2026 and ending before 1 July 2028.", effectiveFrom: "2024-01-01", topics: ["tcsh", "transitional cbcr safe harbour", "de minimis", "simplified etr", "routine profits", "once out", "16%", "17%"], ruleIds: ["OECD-TCSH-2026"], electionIds: ["SH_TCSH", "SH_TCSH_DM", "SH_TCSH_ETR", "SH_TCSH_RP"], href: "/safe-harbours" }),
  p({ id: "LP-SH22-2", sourceId: "OECD-SH-2022-12", ref: "Ch. 2 — Permanent Safe Harbour framework", heading: "Simplified Calculations Safe Harbour framework", text: "The Inclusive Framework agreed a framework under which Simplified Income, Simplified Revenue and Simplified Tax Calculations may substitute for the full GloBE computations in a routine profits test, a de minimis test and an ETR test, with the specific simplified calculations to be developed as Administrative Guidance. A jurisdiction passing any test has its Top-up Tax deemed zero for the year.", effectiveFrom: "2024-01-01", topics: ["simplified calculations", "permanent safe harbour", "framework"], electionIds: ["SH_SCSH"], href: "/safe-harbours" }),
  p({ id: "LP-SH22-3", sourceId: "OECD-SH-2022-12", ref: "Ch. 3 — Transitional penalty relief", heading: "Transitional penalty relief", text: "For Fiscal Years in the Transition Period, no penalties or sanctions should apply in connection with the filing of a GloBE Information Return where the tax administration considers that the MNE Group has taken reasonable measures to ensure the correct application of the GloBE Rules — acting in good faith to understand and comply with the Rules and the domestic law.", effectiveFrom: "2024-01-01", topics: ["penalty relief", "reasonable measures", "good faith", "transition"], gapIds: ["G-AUDIT"], href: "/audit" }),
  p({ id: "LP-SBS26-1", sourceId: "OECD-SBS-2026", ref: "Part 1 — Side-by-Side Safe Harbour", heading: "Side-by-Side Safe Harbour", text: "An MNE Group whose UPE is located in a jurisdiction operating a qualifying domestic minimum tax system alongside the GloBE Rules may elect to treat the IIR and UTPR Top-up Tax for its Constituent Entities located in that jurisdiction — and, for the transitional period, its operations in non-implementing jurisdictions to the extent the package provides — as zero. The group remains subject to Qualified Domestic Minimum Top-up Taxes elsewhere and must still file the GloBE Information Return. Eligibility is recorded through the Central Record process.", effectiveFrom: "2026-01-01", topics: ["side-by-side", "sbs", "united states", "upe jurisdiction", "deemed zero"], ruleIds: ["US-SBS-2026"], electionIds: ["SH_SBS"], href: "/safe-harbours" }),
  p({ id: "LP-SBS26-2", sourceId: "OECD-SBS-2026", ref: "Part 2 — Transitional CbCR Safe Harbour extension", heading: "TCSH extended to Fiscal Years beginning on or before 31 December 2027", text: "The Transition Period of the Transitional CbCR Safe Harbour is extended by one year to Fiscal Years beginning on or before 31 December 2027 and ending before 1 July 2029. The Transition Rate for the simplified ETR test is 17% for Fiscal Years beginning in 2026 and in 2027. The once-out-always-out rule is unchanged.", effectiveFrom: "2026-01-01", effectiveTo: "2029-06-30", topics: ["tcsh", "extension", "2027", "17%", "transition period"], ruleIds: ["OECD-TCSH-2026"], electionIds: ["SH_TCSH", "SH_TCSH_ETR"], href: "/safe-harbours" }),
  p({ id: "LP-SBS26-3", sourceId: "OECD-SBS-2026", ref: "Part 3 — Simplified ETR Safe Harbour", heading: "Simplified ETR Safe Harbour for post-transition years", text: "For Fiscal Years after the Transitional CbCR Safe Harbour, a jurisdiction may be treated as having zero Top-up Tax where its Simplified ETR — Simplified Covered Taxes divided by Simplified Income computed from the Qualified Financial Statements with a defined, shorter list of adjustments — is at or above 15%. The simplified computation contains its own elections (asymmetric FX and pension opt-outs, taxes outside income tax expense, equity-reported taxes, refundable and transferable credit gross-ups, PE simplification, post-year-end and transfer-pricing timing), several of which are group-wide Five-Year Elections that continue to bind if the group later returns to full GloBE computation.", effectiveFrom: "2026-01-01", topics: ["simplified etr", "setr", "safe harbour", "inner elections", "post-transition"], ruleIds: ["OECD-SETR-SH"], electionIds: ["SH_SETR", "SETR_APPLY", "SETR_FX", "SETR_PEN", "SETR_INS", "SETR_SHIP", "SETR_CT_OIE", "SETR_EQTAX", "SETR_QRTC", "SETR_4.5", "SETR_PE", "SETR_PYE", "SETR_TP"], href: "/elections" }),
  p({ id: "LP-SBS26-4", sourceId: "OECD-SBS-2026", ref: "Part 4 — Substance-based Tax Incentive Safe Harbour", heading: "Substance-based Tax Incentive Safe Harbour", text: "A jurisdiction may be treated as having no Top-up Tax where the group's low ETR there is attributable to a Qualified Substance-based Tax Incentive — an incentive whose benefit is computed by reference to eligible payroll costs or eligible tangible-asset expenditure incurred in the jurisdiction, with the qualifying expenditure traced and documented. Incentives keyed to income, such as intellectual-property boxes, and tax holidays not tied to substance expenditure do not qualify. The relief does not displace a Qualified Domestic Minimum Top-up Tax.", effectiveFrom: "2026-01-01", topics: ["sbtish", "substance-based incentive", "boi", "ip box", "tracing", "tax holiday"], ruleIds: ["OECD-SBTISH", "TH-BOI-OPT-2566"], electionIds: ["SH_SBTI", "SETR_SBTI"], gapIds: ["G-BOI"], href: "/safe-harbours" }),
  p({ id: "LP-SBS26-5", sourceId: "OECD-SBS-2026", ref: "Part 5 — UTPR and UPE jurisdiction relief", heading: "Transitional UTPR Safe Harbour extension and UPE Safe Harbour", text: "The Transitional UTPR Safe Harbour of July 2023 is extended: the UTPR Top-up Tax Amount for a UPE jurisdiction with a nominal corporate income tax rate of at least 20% is deemed to be zero for the extended transitional period set in the package. A UPE Safe Harbour gives equivalent relief to the UPE jurisdiction of groups that operate a qualified IIR there, so that no other jurisdiction applies the UTPR to the UPE's own profits.", effectiveFrom: "2026-01-01", topics: ["utpr safe harbour", "upe safe harbour", "20%", "extension"], ruleIds: ["US-SBS-2026", "JP-IIR-2024"], electionIds: ["SH_UTPR", "SH_UPE"], href: "/safe-harbours" }),

  /* ------------------------------------------------------- GIR and records */
  p({ id: "LP-GIR25-1", sourceId: "OECD-GIR-2025", ref: "Part I–III — return structure", heading: "GloBE Information Return — structure and transitional simplified reporting", text: "The return has a General Section (group identification, corporate structure, summary of Top-up Tax by jurisdiction, and the safe harbour and exclusion elections made, identifying the test relied on), and Jurisdictional Sections with the ETR and Top-up Tax computations, election register and allocation of Top-up Tax for each jurisdiction. For Fiscal Years beginning on or before 31 December 2028 and ending before 1 July 2030 the Transitional Simplified Jurisdictional Reporting Framework allows jurisdictional data to be reported in aggregate rather than by Constituent Entity where no Top-up Tax arises. Dissemination follows the central-filing and exchange approach under Qualifying Competent Authority Agreements.", effectiveFrom: "2024-01-01", topics: ["gir", "return structure", "elections", "transitional simplified reporting", "2028", "dissemination"], ruleIds: ["OECD-GIR-XML", "OECD-ELEC-2026"], electionIds: ["SH_TCSH"], gapIds: ["G-FILE"], href: "/gir" }),
  p({ id: "LP-GIRXML-1", sourceId: "OECD-GIR-XML", ref: "XML Schema v1.0 · User Guide", heading: "GIR XML Schema — message structure", text: "The schema (namespace urn:oecd:ties:globe:v2) defines the exchange message: a message header, the filing information, the General Section with group and entity structure, the Summary, the Jurisdiction Sections with ETR computation, elections and Top-up Tax allocation, and the UTPR attribution. Field-level validation, enumerations for election types and correction mechanics are set by the user guide; the schema governs format and exchange, not the substantive computation.", effectiveFrom: "2024-01-01", topics: ["gir xml", "schema", "urn:oecd:ties:globe:v2", "exchange", "validation"], ruleIds: ["OECD-GIR-XML"], gapIds: ["G-FILE"], href: "/gir" }),
  p({ id: "LP-CR-1", sourceId: "OECD-CR", ref: "Central Record — transitional qualified status", heading: "Central Record of legislation with transitional qualified status", text: "A jurisdiction whose IIR, QDMTT or QDMTT Safe Harbour has completed the transitional qualification process — a self-certification questionnaire reviewed by the Inclusive Framework — is listed on the Central Record with the qualified status and the Fiscal Years from which it applies. Listing is relied on by other jurisdictions in applying the Rules (crediting a QDMTT, switching off the IIR and UTPR, applying the QDMTT Safe Harbour) until a full legislative review is completed. A jurisdiction not yet listed has not been found unqualified; its legislation is simply not yet recorded.", effectiveFrom: "2024-01-01", textKind: "summary", topics: ["central record", "qualified status", "transitional", "self-certification", "qdmtt", "iir"], ruleIds: ["TH-QDMTT-2025", "IE-QDMTT-2024", "JP-IIR-2024", "TH-PACK-2567"], gapIds: ["G-ORDER"], href: "/jurisdictions" }),
  p({ id: "LP-COMM26-1", sourceId: "OECD-COMM-2026", ref: "Consolidated Commentary 2026 — status", heading: "Role of the Consolidated Commentary", text: "The Consolidated Commentary is the agreed interpretation of the Model Rules, incorporating the Administrative Guidance issued to the consolidation date. Jurisdictions implementing the Rules are expected to apply them consistently with the Commentary; the GloBE Rules and Commentary together are the reference for whether a domestic rule is 'qualified'. The 2026 consolidation supersedes the 2025 text as the current interpretive source; positions taken under the earlier text remain documented against it.", effectiveFrom: "2024-01-01", textKind: "summary", topics: ["commentary", "interpretation", "consolidated", "administrative guidance"], ruleIds: ["OECD-GloBE-15", "OECD-ELEC-2026"], gapIds: ["G-INTERP"], href: "/rulebook" }),
];
